class Solution {
public:
    int palindromePartition(std::string s, int k) {
        int n = s.size();
        std::vector<std::vector<int>> cost(n, std::vector<int>(n, 0));
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                cost[i][j] = cost[i + 1][j - 1] + (s[i] == s[j] ? 0 : 1);
            }
        }
        std::vector<int> dp(n);
        for (int j = 0; j < n; ++j) dp[j] = cost[0][j];

        for (int p = 2; p <= k; ++p) {
            std::vector<int> nxt(n, 1e9);
            for (int j = p - 1; j < n; ++j) {
                for (int i = p - 1; i <= j; ++i) {
                    nxt[j] = std::min(nxt[j], dp[i - 1] + cost[i][j]);
                }
            }
            dp = std::move(nxt);
        }
        return dp[n - 1];
    }
};

class Solution {
    public int palindromePartition(String s, int k) {
        int n = s.length();
        int[][] cost = new int[n][n];
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                cost[i][j] = cost[i + 1][j - 1] + (s.charAt(i) == s.charAt(j) ? 0 : 1);
            }
        }
        int[] dp = new int[n];
        for (int j = 0; j < n; j++) dp[j] = cost[0][j];

        for (int p = 2; p <= k; p++) {
            int[] nxt = new int[n];
            java.util.Arrays.fill(nxt, 1_000_000_000);
            for (int j = p - 1; j < n; j++) {
                for (int i = p - 1; i <= j; i++) {
                    nxt[j] = Math.min(nxt[j], dp[i - 1] + cost[i][j]);
                }
            }
            dp = nxt;
        }
        return dp[n - 1];
    }
}

var palindromePartition = function(s, k) {
    const n = s.length;
    const cost = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i <= n - len; i++) {
            const j = i + len - 1;
            cost[i][j] = cost[i + 1][j - 1] + (s[i] === s[j] ? 0 : 1);
        }
    }
    let dp = new Array(n);
    for (let j = 0; j < n; j++) dp[j] = cost[0][j];

    for (let p = 2; p <= k; p++) {
        const nxt = new Array(n).fill(Infinity);
        for (let j = p - 1; j < n; j++) {
            for (let i = p - 1; i <= j; i++) {
                nxt[j] = Math.min(nxt[j], dp[i - 1] + cost[i][j]);
            }
        }
        dp = nxt;
    }
    return dp[n - 1];
};
